L["Cap"] = "Limite"
L["Cap right-click turn speed"] = "Limita la rotazione col clic destro"
L["Right-click turning never goes faster than the speed below."] = "La rotazione col clic destro non supera mai la velocità qui sotto."
L["Top turn speed"] = "Velocità massima di rotazione"
L["The fastest you can turn."] = "La rotazione più veloce possibile."
L["Ease back over"] = "Ritorno graduale in"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "Quanto ci mette la tua velocità di visuale del mouse a tornare dopo che rallenti."
L["Ramp up right-click turn speed"] = "Accelera la rotazione col clic destro"
L["Each right-click turn starts slow and builds up to your own speed."] = "Ogni rotazione col clic destro parte lenta e sale fino alla tua velocità."
L["Start at"] = "Parti da"
L["%d%% of your speed"] = "%d%% della tua velocità"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "Con che velocità parte una rotazione, come quota della tua velocità di visuale del mouse."
L["Up to full speed over"] = "Velocità piena in"
L["How long a turn takes to build up to full speed."] = "Quanto ci mette una rotazione ad arrivare alla velocità piena."
L["Slow looking up and down too"] = "Rallenta anche lo sguardo su e giù"
L["Looking up and down slows by the same share as turning."] = "Guardare su e giù rallenta della stessa quota della rotazione."
L["Turns the whole Atmosphere hub on or off at once."] = "Attiva o disattiva in un colpo l'intero gruppo Atmosfera."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "L'aspetto del mondo di gioco in CineMode: vignettatura, luce delle locande, meteo e profondità di campo."
L["Pick where and when each effect shows in CineMode."] = "Scegli dove e quando appare ogni effetto in CineMode."
L["Shows all the time in CineMode, fights included."] = "Visibile sempre in CineMode, combattimenti compresi."
L["Soft dark edges that draw the eye to the middle."] = "Bordi scuri e morbidi che attirano lo sguardo al centro."
L["Indoors in an inn, a soft firelit glow replaces the outdoor tint."] = "Al chiuso in una locanda, una calda luce di focolare sostituisce la tinta esterna."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "Pioggia, neve e tempeste di sabbia colorano la scena, di più col maltempo intenso."
L["Reduce view distance in bad weather"] = "Riduci la visuale col maltempo"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Riduce la distanza visiva durante pioggia, neve o tempeste di sabbia, di più quanto più sono intense."
L["A soft haze around the screen edges in the camera modes."] = "Una leggera foschia attorno ai bordi dello schermo nelle modalità telecamera."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "Le impostazioni grafiche del gioco una per una, condivise da tutti i profili su questo computer."
L["Uses the settings below, or the game's own when turned off."] = "Usa le impostazioni qui sotto, o quelle del gioco se disattivato."
